if _cython_generator_type is not None:
    try: Generator = _module.Generator
    except AttributeError: pass
    else: Generator.register(_cython_generator_type)
if _cython_coroutine_type is not None:
    try: Coroutine = _module.Coroutine
    except AttributeError: pass
    else: Coroutine.register(_cython_coroutine_type)

() => {
        const out = {};
        const num = (s) => {
            if (s == null) return null;
            const v = parseFloat(String(s).replace(/[^0-9,.-]/g, '')
                                          .replace(/\.(?=\d{3}\b)/g, '')
                                          .replace(',', '.'));
            return Number.isFinite(v) ? v : null;
        };
        const isProduct = (n) => {
            if (!n) return false;
            const t = Array.isArray(n['@type']) ? n['@type'] : [n['@type']];
            return t.includes('Product') || t.includes('ProductGroup');
        };
        // 1) JSON-LD Product (파싱 성공 시)
        for (const s of document.querySelectorAll('script[type="application/ld+json"]')) {
            let data; try { data = JSON.parse(s.textContent); } catch (e) { continue; }
            const nodes = Array.isArray(data) ? data : (data['@graph'] || [data]);
            for (const raw of nodes) {
                if (!isProduct(raw)) continue;
                let offers = raw.offers || {};
                if (Array.isArray(offers)) offers = offers[0] || {};
                if (offers.price != null && out.price == null) out.price = String(offers.price);
                if (offers.availability && out.inventory == null)
                    out.inventory = String(offers.availability).split('/').pop();
                const agg = raw.aggregateRating || {};
                if (agg.ratingValue != null && out.rating == null) out.rating = num(agg.ratingValue);
                if (out.review_count == null)
                    out.review_count = agg.reviewCount || agg.ratingCount || null;
            }
        }
        // 2) DOM 폴백 (But ld+json 은 raw 제어문자로 파싱 실패가 잦아 이 경로가 실질 주력).
        //    현재가는 .price-value (leaf). .price/.price-container 는 취소선 구가(.old-price--crossed)
        //    까지 감싸 "1 199,99€1 399,99€" 로 병합되므로 쓰지 않는다 (NEWAAAAA-9 실측).
        if (out.price == null) {
            const pe = document.querySelector('.price-value');
            const v = pe ? num(pe.textContent) : null;
            if (v != null) out.price = String(v);
        }
        if (out.rating == null) {
            const re = document.querySelector('.rating-value');
            if (re) out.rating = num(re.textContent);
        }
        if (out.price === 'null') delete out.price;
        return out;
    }
